<?php require __DIR__.'/config.php';$u=require_login();if(is_super_admin())redirect('admin.php');$b=require_business();$pdo=db();if(($b['account_status']??'active')!=='active')redirect('account.php');if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='hero') { verify_csrf(); if(!can('settings')) { http_response_code(403); exit('Forbidden'); } try { $newHero=hero_upload('hero_image'); $oldHero=$b['hero_image']??null; $s=$pdo->prepare('UPDATE businesses SET hero_image=?,updated_at=NOW() WHERE id=?'); $s->execute([$newHero,$b['id']]); delete_hero_file($oldHero); audit((int)$b['id'],(int)$u['id'],'business.hero_updated','Primary hero image replaced from dashboard'); flash('Hero image updated. Customers will see it at the top after scanning your QR code.'); } catch(Throwable $e) { flash($e->getMessage(),'error'); } redirect('index.php'); }if(($b['onboarding_status']??'new')!=='complete')redirect('onboarding.php');if(!current_plan((int)$b['id'])){flash('Your SERV subscription is not active. Please contact Super Admin to activate or renew your plan.','error');redirect('onboarding.php');}$s=$pdo->prepare("SELECT COALESCE(SUM(total),0) FROM orders WHERE business_id=? AND status IN ('served','completed') AND DATE(created_at)=CURDATE()");$s->execute([$b['id']]);$sales=(float)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM orders WHERE business_id=? AND status IN ('new','accepted','preparing','ready','serving')");$s->execute([$b['id']]);$pending=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT COUNT(*) FROM orders WHERE business_id=? AND DATE(created_at)=CURDATE()");$s->execute([$b['id']]);$today=(int)$s->fetchColumn();$s=$pdo->prepare("SELECT o.*,l.name location_name,u.name served_name FROM orders o LEFT JOIN locations l ON l.id=o.location_id LEFT JOIN users u ON u.id=o.served_by WHERE o.business_id=? ORDER BY o.created_at DESC LIMIT 6");$s->execute([$b['id']]);$orders=$s->fetchAll();include __DIR__.'/app/layout_top.php';?><div class="page-head"><div><div class="eyebrow"><?=e($b['name'])?></div><h1>Good day, <?=e($u['name'])?> 👋</h1><p>Everything happening in your hospitality operation.</p></div></div><section class="panel dashboard-hero-manager">
<div class="section-head"><div><div class="eyebrow">PUBLIC PROFILE</div><h3 style="margin:3px 0 4px">Your hero image</h3><p class="small muted" style="margin:0">This is the cover photo customers see first when they scan your QR code.</p></div><span class="badge">JPG · PNG · WebP</span></div>
<div class="dashboard-hero-grid">
<div class="dashboard-hero-preview<?=!empty($b['hero_image'])?' has-image':''?>" style="background-image:<?=!empty($b['hero_image'])?'linear-gradient(180deg,rgba(5,12,16,.12),rgba(5,12,16,.72)),url(\''.e($b['hero_image']).'\')':'linear-gradient(135deg,#2E6F8E,#174B63)'?>">
